Closes #959 

This is due to the change in R 3.4.0

<img width="748" alt="image" src="https://user-images.githubusercontent.com/8368933/151661359-49b3e479-0023-4173-96a9-a7ade2a104cc.png">

## Example App

```r
library(shiny)
ui <- fluidPage(
  actionButton("add", "Add Row"),
  DT::DTOutput("tbl")
)
sample_row <- function() {
  row <- sample(letters, 1L)
  a <- sample(0:9, 1L)
  b <- sample(letters, 3) |> paste0(collapse = "")
  list(row, A = a, B = b)
}
df <- rbind(
  "a" = c("A" = 1L, "B" = "abc"),
  "b" = c("A" = 2L, "B" = "bcd")
)

server <- function(input, output, session) {
  output$tbl <- DT::renderDT({
    df
  }, server = FALSE)
  proxy <- DT::dataTableProxy("tbl")
  observeEvent(input$add, {
    DT::addRow(proxy, sample_row())
  })
}
shiny::runApp(mget(c("ui", "server")))
```

With this simple example app, the first user will see a delay before it shows the table, but other users who visit the app should see it instantly.

```
library(shiny)
library(DT)
shinyApp(
  ui = fluidPage(DTOutput('tbl')),
  server = function(input, output) {
    output$tbl <- renderDT({
        message("Computing...")
        Sys.sleep(2)
        iris
      }, 
      server = FALSE, 
      options = list(lengthChange = FALSE)
    ) %>%
      bindCache(1)
    
    # Note that bindCache() must be used with renderDT(server=FALSE)
  }
)
```

This PR modifies the event listeners for `row_last_clicked` and `cell_clicked` events to always send the value of the clicked row or cell when clicked. Previously, the value was sent only if the clicked row had not changed.

The motivation for this is to be able to write `row_last_clicked` "event handlers" in shiny, for example adding or removing the last clicked row to the collection of selected rows when the data is being filtered using non-DT inputs elsewhere in the app.

Apologies for not first opening an issue, I thought it might be easier to just propose the changes.

<details><summary>Here's a small example app</summary>

```r
library(shiny)
library(DT)
library(dplyr)

ui <- fluidPage(
  tags$p("This is a simple demo, but the filtering UI could be much more complicated."),
  selectizeInput("homeworld", "Homeworld", choices = unique(starwars$homeworld), multiple = TRUE),
  dataTableOutput("table")
)

server <- function(input, output, session) {
  global_selection <- reactiveVal(NULL)
  
  # Global dataset
  starwars <- dplyr::starwars %>% mutate(id = row_number())
  
  # Data set shown in app based on current filters
  starwars_view <- reactive({
    if (isTruthy(input$homeworld)) {
      starwars %>% filter(homeworld %in% input$homeworld)
    } else {
      starwars
    }
  })
  
  # Limit displayed columns to a small subset for this demo
  prep_starwars <- function(x) {
    x[, c("name", "height", "homeworld", "species")]
  }
  
  # Initialize the datatable
  output$table <- renderDataTable({
    datatable(
      prep_starwars(starwars),
      selection = list(mode = "multiple", target = "row")
    )
  })
  
  # Watch the last clicked event and handle each click
  observeEvent(input$table_row_last_clicked, {
    clicked_id <- starwars_view()$id[input$table_row_last_clicked]
    if (!clicked_id %in% global_selection()) {
      # Add row ID to global selection
      global_selection(c(global_selection(), clicked_id))
    } else {
      # remove row ID from global selection
      global_selection(setdiff(global_selection(), clicked_id))
    }
  })
  
  # Update the datatable in place when data or selection change
  observeEvent(starwars_view(), {
    dataTableProxy("table") %>% 
      replaceData(prep_starwars(starwars_view())) %>% 
      selectRows(which(starwars_view()$id %in% global_selection()))
  })
  
  observeEvent(global_selection(), {
    dataTableProxy("table") %>% 
      selectRows(which(starwars_view()$id %in% global_selection()))
  })
}

shinyApp(ui, server)
```
</details>

Right now, the `server` argument in `renderDT()` doesn't react to the inputs in Shiny. This PR enables it.

It's trivial but I personally find it's very useful when testing.

```r
library(shiny)

ui = fluidPage(sidebarLayout(
  sidebarPanel(
    radioButtons('server','server',c('TRUE','FALSE'))
  ),
  mainPanel(
    DT::DTOutput('tbl')    
  )
))
server = function(input, output, session) {
  output$tbl = DT::renderDT({
    tbl = data.frame(A = rnorm(10), B = rnorm(10))
  }, server = as.logical(input$server))
}
shiny::runApp(list(ui = ui, server = server), port = 6435)
```

Closes #467 

See https://datatables.net/blog/2017-12-31 for more info about this plugin.

### Example code

Try to resize the red area. With this plugin, the table will fit it well. Otherwise, it will be fixed to a certain height.

```r
library(shiny)
ui <- tags$html(
  tags$head(
    tags$link(
      rel = "stylesheet", href = "//code.jquery.com/ui/1.12.1/themes/base/jquery-ui.css"
    ),
    tags$script(
      src = "https://code.jquery.com/ui/1.12.1/jquery-ui.js"
    ),
    tags$script(
      DT::JS("$(function() {$('#resizable').resizable();});")
    )
  ),
  tags$body(
    radioButtons('scrollresize', 'scrollresize', choices = c('TRUE', 'FALSE')),
    div(
      id = 'resizable',
      style = 'height:500px;background-color:red;',
      DT::DTOutput('tbl', height = '100%')
    )
  )
)

server <- function(input, output, session) {
  dat <- iris[1:50,]
  output$tbl <- DT::renderDT(
    if (input$scrollresize == 'TRUE') {
      DT::datatable(
        dat, plugins = 'scrollResize',
        options = list(scrollResize = TRUE, paging = FALSE, scrollY = '100px', scrollCollapse = TRUE)
      )
    } else {
      DT::datatable(dat, options = list(paging = FALSE, scrollY = '100px', scrollCollapse = TRUE))
    }
  )
}

shinyApp(ui, server)
```

Closes #705

When scrollX/Y is enabled, the column selection won't work in `row+column` mode. The reason is that the datatable library will seperate the footer from the body when there's a scroller. The old foot selector won't work somehow. This patch uses the datatables' api to select the footer, which should be robuster (at least ok for this case).

# Example Code

```r
library(shiny)
library(DT)

ui = basicPage(verbatimTextOutput('col_select'), DTOutput("tbl"))

server = function(input, output) {
  output$tbl = DT::renderDT({
    DT::datatable(
      iris,
      selection = list(mode = 'multiple', target = 'row+column'),
      options = list(scrollX = TRUE, scrollY = "300px")
    )
  })
  output$col_select = renderPrint({
    input$tbl_columns_selected
  })
}
shinyApp(ui = ui, server = server)
```

