Closes #645

Since `cell_edit` will only be triggered when the value shown on the table has been changed so it's almost always what user expects.

### Steps to Reproduce

1. Run the app
1. Edit any cell to any value, e.g., cell(1,1) to "aaa" 
1. Click the button
1. Edit again with the same value "aaa"

Previously the reactive events won't be triggered. With this PR, it will.


### Code

```r
library(shiny)
library(DT)
shinyApp(
  ui = fluidPage(
    fluidRow(
      verbatimTextOutput('edit_content'),
      column(2, actionButton('refresh', 'Refresh Data', icon = icon('refresh'))),
      column(10, DT::dataTableOutput('foo'))
    )
  ),
  server = function(input, output, session) {
    loopData = reactive({
      input$refresh
      iris
    })
    output$foo = DT::renderDataTable(isolate(loopData()), editable = TRUE)
    proxy = dataTableProxy('foo')
    observe({
      replaceData(proxy, loopData(), resetPaging = FALSE)
    })
    observeEvent(input$foo_cell_edit, {
      print("an edit occured")
    })
    output$edit_content <- renderPrint({
      print(paste(Sys.time(), "trigger"))
      str(input$foo_cell_edit)
    })
  }
)
```

Normally, htmlwidgets don't require any work to be compatible with Shiny async. But DT is different because it has these `currentSession`/`currentOutputName` variables that rely on all of the rendering code being executed synchronously (as these variables are maintained using the call stack). Maintaining these kinds of "contextual" global variables is harder with async but still possible, as this is what [promise domains](https://gist.github.com/jcheng5/b1c87bb416f6153643cd0470ac756231) were invented for.

Example app:

```r
library(shiny)
library(DT)
library(promises)
library(future)
plan(multiprocess)


tblOutputUI <- function(id) {
  ns <- NS(id)
  DT::dataTableOutput(ns("table"))
}

tblOutput <- function(input, output, session, df) {
  output$table <- DT::renderDataTable({
    future({ Sys.sleep(0.1); df }) %...>%
      identity()
  })
}


ui <- fluidPage(
  numericInput("nrow", "Number of rows", 50),
  DT::dataTableOutput("table"),
  tblOutputUI("one")
)

server <- function(input, output, session) {
  output$table <- DT::renderDataTable({
    future({ Sys.sleep(0.1); cars }) %...>%
      head(input$nrow)
  })
  
  callModule(tblOutput, "one", mtcars)
}

shinyApp(ui, server)
```

Closes #533 

Ref to #513 #496 

## Description

Introduce a new option `DT.TOJSON_ARGS` to control the NA's printing value, mainly.  

**UPDATE** The default value on the server-side processing mode is set to `getOptions("DT.TOJSON_ARGS", getOptions("htmlwidgets.TOJSON_ARGS")` in order to preserve the same behavior as the client mode, on which `htmlwidgets` packages will pick up`htmlwidgets.TOJSON_ARGS` by default.

see https://github.com/ramnathv/htmlwidgets/blob/e3097fa5ff31402f7fce60f8a2e86147a9b983b2/R/utils.R#L31-L32




## Example

```r
library(shiny)

dat <- data.frame(
  a = c(5, 6, NA, Inf, 10, 100),
  b = c(letters[1:4], NA, NA),
  c = factor(c(letters[1:4], NA, NA)),
  stringsAsFactors = FALSE
)

shinyApp(
  ui = fluidPage(
    radioButtons("na_inf", "na_inf", c("no-option", "null", "string"), inline = TRUE),
    verbatimTextOutput("text"),
    fluidRow(
      column(
        6,
        h3("client mode"),
        DT::dataTableOutput("client_dt")
      ),
      column(
        6,
        h3("server mode"),
        DT::dataTableOutput("server_dt")
      )
    )
  ),
  server = function(input,output){
    observe(
      if (req(input$na_inf) == "no-option") {
        if (!is.null(getOption("DT.TOJSON_ARGS"))) options("DT.TOJSON_ARGS" = NULL)
      } else {
        options("DT.TOJSON_ARGS" = list(na = input$na_inf))
      }
    )
    output$text <- renderPrint({
      input$na_inf
      str(getOption("DT.TOJSON_ARGS"))
    })
    output$client_dt <- DT::renderDataTable({
      input$na_inf
      DT::datatable(head(dat))
    }, server = FALSE)
    output$server_dt <- DT::renderDataTable({
      input$na_inf
      DT::datatable(head(dat))
    }, server = TRUE)
  },
  options = list(port = 6815)
)
```

Closes #525 

Some user wants to implement some heavy customized datatable style, such as in #525, a child table for each row. The current implement `cleanDataFrame()` doesn't support this and leads to a broken datatable in the server-side processing mode. This PR is going to fix this. 


### Example Code

- __Before this PR__ : The browser will throw an error says 

```
DataTables warning: table id=DataTables_Table_0 - Error in `[<-.data.frame`(`*tmp*`, , j, value = list(structure(list(A = c("A", : replacement element 1 is a matrix/data frame of 3 rows, need 2
```

- __After this PR__ : It works.

---

```r
library(data.table)
library(shiny)
library(DT)

dat <- local({
  n <- 6
  DT <- data.table(
    HEADER = '&#9658;',
    A = rep_len(LETTERS, n),
    B = rep_len(1:10, n),
    C = rep_len(c("GRP1", "GRP2"), n)
  )
  DT[, .(D=.(.SD)), by = .(HEADER, C)]
})


callback_js <-
  JS("
var init_tbl = function(id) {
  return '<table id=\"' + id + '\" class=\"display\" width=\"100%\"></table>';
}

var init_datatable = function(id, d) {
  id = '#'+id;
  $(id).DataTable({
    data: d,
    columns: [
    { data: 'A' },
    { data: 'B' }
    ]  
  }).draw();
}
var sub_tbl_id = 0;
table.on('click', 'td.details-control', function() {
  var table = $(this).closest('table');
  var td = $(this);
  var row = $(table).DataTable().row(td.closest('tr'));
if (row.child.isShown()) {
  row.child.hide();
  td.html('&#9658;');
} else {
  sub_tbl_id = sub_tbl_id + 1;
  var id = 'sub_tbl_id_' + sub_tbl_id;
  row.child(init_tbl(id)).show();
  init_datatable(id, row.data()[3]);
  td.html('&#9660;');
}
})
     ")

runApp(list(
  ui = fluidPage(DT::DTOutput("tbl")),
  server = function(input, output) {
    output$tbl <- DT::renderDT({
      datatable(
        dat,
        escape = FALSE,
        options = list(
          columnDefs = list(
            list(orderable = FALSE, className = 'details-control', targets = 1),
            list(visible = FALSE, targets = -1)
          )
        ),
        callback = callback_js
      )
    }, server = TRUE)
  }), port = 33333)

```

